    # Locate the large, connected, nonzero panel.
    seen = set()
    panel_cells = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if (0 <= nx < H and 0 <= ny < W and
                            grid[nx][ny] != 0 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(comp) > len(panel_cells):
                panel_cells = comp

    r0 = min(r for r, c in panel_cells)
    r1 = max(r for r, c in panel_cells)
    c0 = min(c for r, c in panel_cells)
    c1 = max(c for r, c in panel_cells)
    panel = [row[c0:c1+1] for row in grid[r0:r1+1]]
    h, w = len(panel), len(panel[0])

    # The single-cell colors inside the panel are corner anchors.
    positions = {}
    for r in range(h):
        for c in range(w):
            color = panel[r][c]
            if color != 1:
                positions.setdefault(color, []).append((r, c))
    anchors = {color: cells[0] for color, cells in positions.items()
               if len(cells) == 1}

    # Outside dots indicate the desired corner for each anchor color.
    outside = []
    for r in range(H):
        for c in range(W):
            if not (r0 <= r <= r1 and c0 <= c <= c1):
                color = grid[r][c]
                if color in anchors:
                    outside.append((r, c, color))

    targets = {}
    if outside:
        minr = min(r for r, c, color in outside)
        maxr = max(r for r, c, color in outside)
        minc = min(c for r, c, color in outside)
        maxc = max(c for r, c, color in outside)
        for r, c, color in outside:
            targets[color] = (
                "T" if r < (minr + maxr) / 2 else "B"
            ) + (
                "L" if c < (minc + maxc) / 2 else "R"
            )

    # Each transform returns both the mapped coordinate and output dimensions.
    transforms = [
        (lambda r, c: (r, c), h, w),
        (lambda r, c: (c, h-1-r), w, h),
        (lambda r, c: (h-1-r, w-1-c), h, w),
        (lambda r, c: (w-1-c, r), w, h),
        (lambda r, c: (h-1-r, c), h, w),
        (lambda r, c: (r, w-1-c), h, w),
        (lambda r, c: (c, r), w, h),
        (lambda r, c: (w-1-c, h-1-r), w, h),
    ]

    def quadrant(r, c, hh, ww):
        return ("T" if r < hh / 2 else "B") + ("L" if c < ww / 2 else "R")

    best = transforms[0]
    best_score = -1
    for fn, oh, ow in transforms:
        score = 0
        for color, (r, c) in anchors.items():
            if color in targets:
                rr, cc = fn(r, c)
                score += quadrant(rr, cc, oh, ow) == targets[color]
        if score > best_score:
            best_score = score
            best = (fn, oh, ow)

    fn, oh, ow = best
    out = [[1] * ow for _ in range(oh)]
    for r in range(h):
        for c in range(w):
            rr, cc = fn(r, c)
            out[rr][cc] = panel[r][c]
    return out
